export const questions: Question[] = [
  // ─── Types of rights ──────────────────────────────────────────────
  { id: "q-nhrc01", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Which of the following best describes NATURAL rights?", options: ["Rights created by the government through legislation", "Rights that belong to every person simply because they are human — universal and inalienable", "Rights supported only by the moral conscience of society", "Rights enforceable only through the Supreme Court"], correctOptionIds: [1], explanation: "Natural rights belong to every person simply because they are human. They are not created by any government but are considered part of human nature itself — right to life, liberty and property — and are universal and inalienable.", optionExplanations: {"0":"That describes legal rights.","1":"Correct.","2":"That describes moral rights.","3":"That describes constitutional remedies for Fundamental Rights."}, difficulty: "easy", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [2], tags: ["natural-rights","types-of-rights"] },
  { id: "q-nhrc02", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Which statement about the relationship between Fundamental Rights and Constitutional Rights is correct?", options: ["All Constitutional Rights are Fundamental Rights", "All Fundamental Rights are Constitutional Rights, but not all Constitutional Rights are Fundamental Rights", "The two categories are entirely separate", "Constitutional Rights are always more enforceable than Fundamental Rights"], correctOptionIds: [1], explanation: "Both are subcategories of legal rights. Fundamental Rights are in Part III (Art 12-35) and are enforceable under Art 32 and Art 226. Constitutional Rights are conferred by the Constitution but lie outside Part III — the right to vote (Art 326) and the right to property (Art 300A) being the standard examples. Hence all FRs are Constitutional Rights, but not vice versa.", optionExplanations: {"0":"Reversed — Art 326 and Art 300A are constitutional but not fundamental.","1":"Correct.","2":"They overlap: FRs are a subset.","3":"FRs enjoy stronger enforcement, via Art 32."}, difficulty: "medium", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [2], tags: ["fundamental-rights","constitutional-rights","article-300a","article-326"] },
  { id: "q-nhrc03", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "What is the position of the Right to Property in India today? (UPSC 2021)", options: ["Legal right available to citizens only", "Legal right available to any person", "Fundamental Right available to citizens only", "Neither a Fundamental Right nor a legal right"], correctOptionIds: [1], explanation: "The right to property was removed from Part III by the 44th Amendment and now exists as a constitutional/legal right under Article 300A, which uses the words 'no PERSON' — making it available to any person, not merely citizens.", optionExplanations: {"0":"Art 300A protects any person, not only citizens.","1":"Correct.","2":"It ceased to be a Fundamental Right after the 44th Amendment.","3":"It remains a legal right under Art 300A."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [2,14], tags: ["right-to-property","article-300a","pyq-2021"] },

  // ─── UDHR ─────────────────────────────────────────────────────────
  { id: "q-nhrc04", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The Universal Declaration of Human Rights was adopted by the UN General Assembly on:", options: ["24 October 1945", "10 December 1948", "26 November 1949", "16 December 1966"], correctOptionIds: [1], explanation: "The UDHR was adopted by the UN General Assembly on 10 December 1948 — the first international document to recognise that all human beings are born free and equal in dignity and rights. It was drafted in the aftermath of the Second World War.", optionExplanations: {"0":"That is UN Day (Charter came into force).","1":"Correct. 10 December 1948.","2":"That is when the Indian Constitution was adopted.","3":"1966 = the ICCPR and ICESCR."}, difficulty: "easy", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [8], tags: ["udhr","1948","unga"] },
  { id: "q-nhrc05", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The UDHR consists of:", options: ["A preamble and 30 Articles, and is NOT a legally binding treaty", "A preamble and 50 Articles, legally binding on all UN members", "22 Articles with binding force", "Only a declaration of principles with no articles"], correctOptionIds: [0], explanation: "The UDHR has a preamble and 30 Articles covering civil, political, economic, social and cultural rights. It is not a legally binding treaty, but has become the moral and political foundation for later international conventions and national constitutions, including India's.", optionExplanations: {"0":"Correct.","1":"Neither 50 Articles nor binding.","2":"Not 22 Articles.","3":"It does contain 30 Articles."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [8], tags: ["udhr","30-articles","non-binding"] },
  { id: "q-nhrc06", subject: "polity", lessonIds: ["nhrc-01"], type: "multiple-statements", prompt: "Other than the Fundamental Rights, which of the following part(s) of the Constitution of India reflect the principles and provisions of the Universal Declaration of Human Rights (1948)? (UPSC 2020)\n1. Preamble\n2. Directive Principles of State Policy\n3. Fundamental Duties", statements: ["Preamble", "Directive Principles of State Policy", "Fundamental Duties"], options: ["1 and 2 only", "2 only", "1 and 3 only", "1, 2 and 3"], correctOptionIds: [3], explanation: "All three reflect UDHR principles. The Preamble's Justice-Liberty-Equality-Fraternity echoes the UDHR's four pillars; the DPSPs embody its socio-economic rights (Art 38, 39, 41, 45); and Fundamental Duties under Art 51A — dignity of women 51A(e), composite culture 51A(f), scientific temper 51A(h) — mirror its ethos.", optionExplanations: {"0":"Fundamental Duties also reflect the UDHR.","1":"The Preamble and Fundamental Duties do too.","2":"The DPSPs are the clearest reflection of UDHR socio-economic rights.","3":"Correct. All three."}, difficulty: "medium", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [9,14], tags: ["udhr","pyq-2020","preamble","dpsp","fundamental-duties"] },
  { id: "q-nhrc07", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The four enduring principles on which the UDHR rests are:", options: ["Sovereignty, Socialism, Secularism, Democracy", "Dignity, Liberty, Equality and Brotherhood", "Justice, Order, Security, Peace", "Life, Liberty, Property, Happiness"], correctOptionIds: [1], explanation: "The UDHR rests on dignity, liberty, equality and brotherhood — which the Preamble of the Indian Constitution directly echoes through justice, liberty, equality and fraternity assuring the dignity of the individual.", optionExplanations: {"0":"Those are Preamble descriptors of the Indian State.","1":"Correct.","2":"Not the UDHR framing.","3":"That is the Lockean/American formulation."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [8], tags: ["udhr","four-principles","dignity-liberty-equality-brotherhood"] },

  // ─── NHRC: basics ─────────────────────────────────────────────────
  { id: "q-nhrc08", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The National Human Rights Commission is:", options: ["A constitutional body under Article 338", "A statutory body under the Protection of Human Rights Act, 1993", "An executive body created by a Cabinet resolution", "A UN-established body operating in India"], correctOptionIds: [1], explanation: "The NHRC is a STATUTORY body created by the Protection of Human Rights Act, 1993 and established on 12 October 1993 — not a constitutional body. This is a standard prelims discrimination against the NCSC/NCST, which ARE constitutional (Art 338, 338A).", optionExplanations: {"0":"Art 338 is the National Commission for Scheduled Castes.","1":"Correct.","2":"It is statutory, not a mere executive creation.","3":"It is an Indian statutory body designed to conform to the UN-endorsed Paris Principles."}, difficulty: "easy", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [3], tags: ["nhrc","statutory","phra-1993"] },
  { id: "q-nhrc09", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The NHRC was established on:", options: ["26 January 1993", "12 October 1993", "10 December 1993", "1 April 1994"], correctOptionIds: [1], explanation: "The NHRC was established on 12 October 1993 under the Protection of Human Rights Act, 1993. Its working is also governed by the NHRC (Procedure) Regulations, 1994.", optionExplanations: {"0":"Not 26 January.","1":"Correct. 12 October 1993.","2":"10 December is Human Rights Day (UDHR anniversary).","3":"1994 is the year of the Procedure Regulations."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [3], tags: ["nhrc","12-october-1993"] },
  { id: "q-nhrc10", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The three-tier human rights structure created by the Protection of Human Rights Act, 1993 consists of:", options: ["NHRC, SHRCs and Human Rights Courts", "NHRC, NCW and NCM", "NHRC, the Supreme Court and High Courts", "NHRC, CVC and Lokpal"], correctOptionIds: [0], explanation: "Parliament created a three-tier structure: the NHRC at the national level, State Human Rights Commissions at the state level, and Human Rights Courts at the district level — ensuring both accountability and accessibility.", optionExplanations: {"0":"Correct.","1":"Those are separate commissions for specific groups.","2":"Courts are the constitutional remedy, not the Act's tiers.","3":"Those are anti-corruption bodies."}, difficulty: "easy", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [3], tags: ["three-tier","shrc","human-rights-courts"] },
  { id: "q-nhrc11", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The Paris Principles (1993), which the NHRC's design seeks to conform to, relate to:", options: ["Climate change obligations", "The autonomy, independence and accountability of national human rights institutions", "Refugee protection standards", "Rules on prison conditions"], correctOptionIds: [1], explanation: "The UN-endorsed Paris Principles (1993) set standards for the autonomy, independence, pluralism, adequate funding and accountability of national human rights institutions. GANHRI accredits NHRIs against these principles — and India's NHRC was downgraded from 'A' grade in 2017.", optionExplanations: {"0":"That is the Paris Agreement, 2015 — a different instrument.","1":"Correct.","2":"That is the 1951 Refugee Convention.","3":"Prison standards = the UN Mandela Rules (2015)."}, difficulty: "medium", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [3], tags: ["paris-principles","1993","nhri","ganhri"] },

  // ─── NHRC: composition & appointment ──────────────────────────────
  { id: "q-nhrc12", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The composition of the NHRC is:", options: ["A Chairperson and 2 members", "A Chairperson, 5 full-time members and 7 ex-officio members", "A Chairperson and 10 members, all full-time", "A Chairperson and 4 members with no ex-officio membership"], correctOptionIds: [1], explanation: "The NHRC comprises a Chairperson, five full-time members, and seven ex-officio (deemed) members — the chairpersons of the National Commissions for SCs, STs, Women, Minorities, Backward Classes and Protection of Child Rights, plus the Chief Commissioner for Persons with Disabilities.", optionExplanations: {"0":"That is an SHRC's composition.","1":"Correct.","2":"There are five full-time members plus seven ex-officio.","3":"There ARE ex-officio members."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [3], tags: ["nhrc","composition","ex-officio"] },
  { id: "q-nhrc13", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Who is eligible to be Chairperson of the NHRC today?", options: ["Only a retired Chief Justice of India", "A retired Chief Justice of India or a retired Judge of the Supreme Court", "Any serving Judge of the Supreme Court", "Only a retired Chief Justice of a High Court"], correctOptionIds: [1], explanation: "The Chairperson must be a retired Chief Justice of India OR a retired Judge of the Supreme Court — the second option was added by the 2019 amendment. A 2004 UPSC question whose answer was 'only a retired Chief Justice of India' reflected the pre-2019 position.", optionExplanations: {"0":"That was the position BEFORE the 2019 amendment.","1":"Correct.","2":"A serving judge is not eligible.","3":"That is the SHRC chairperson's qualification."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [3,14], tags: ["nhrc-chairperson","2019-amendment","eligibility"] },
  { id: "q-nhrc14", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Which of the following is NOT an ex-officio member of the NHRC?", options: ["Chairperson of the National Commission for Women", "Chairperson of the National Commission for Backward Classes", "Comptroller and Auditor General of India", "Chief Commissioner for Persons with Disabilities"], correctOptionIds: [2], explanation: "The seven ex-officio members are the chairpersons of the National Commissions for SCs, STs, Women, Minorities, Backward Classes and Protection of Child Rights, plus the Chief Commissioner for Persons with Disabilities. The CAG is not among them.", optionExplanations: {"0":"Is an ex-officio member.","1":"Is an ex-officio member.","2":"Correct answer — the CAG is not an NHRC member.","3":"Is an ex-officio member."}, difficulty: "medium", skill: "elimination", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [3,4], tags: ["ex-officio-members","elimination"] },
  { id: "q-nhrc15", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Regarding the full-time members of the NHRC, which is correct?", options: ["All five must be retired judges", "Three must have knowledge or practical experience of human rights, of whom at least one must be a woman", "There is no requirement of a woman member", "All members must be serving civil servants"], correctOptionIds: [1], explanation: "Of the five full-time members: one is/was a Supreme Court judge, one is/was a Chief Justice or judge of a High Court, and three have knowledge or practical experience of human rights — with at least one of them mandatorily a woman.", optionExplanations: {"0":"Only two of the five must be judges.","1":"Correct.","2":"A woman member is mandatory — tested in the 1999 UPSC prelims.","3":"No such requirement."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [3], tags: ["nhrc-members","woman-member","mandatory"] },
  { id: "q-nhrc16", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The NHRC selection committee does NOT include:", options: ["The Prime Minister", "The Speaker of the Lok Sabha", "The Chief Justice of India", "The Deputy Chairman of the Rajya Sabha"], correctOptionIds: [2], explanation: "The six-member committee is: the PM (chairperson), the Home Minister, the Speaker of the Lok Sabha, the Deputy Chairman of the Rajya Sabha, and the Leaders of Opposition in both Houses. The CJI is NOT on it — one reason critics call the appointment process executive-dominated.", optionExplanations: {"0":"Is the chairperson of the committee.","1":"Is a member.","2":"Correct answer — the CJI is not a member.","3":"Is a member (note: Deputy Chairman, not Chairman)."}, difficulty: "hard", skill: "elimination", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [3], tags: ["selection-committee","cji-not-member","executive-dominance"] },
  { id: "q-nhrc17", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The term of office of the NHRC Chairperson and members is:", options: ["5 years or age 70", "3 years or age 70, whichever is earlier", "6 years or age 65", "4 years or age 62"], correctOptionIds: [1], explanation: "The term is 3 years or until age 70, whichever is earlier — reduced from FIVE years by the 2019 amendment, which in exchange made members eligible for reappointment. The same 3-year/70 rule now applies to SHRCs.", optionExplanations: {"0":"5 years was the PRE-2019 position.","1":"Correct.","2":"Not this pattern.","3":"4 years/65 is the CVC."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [4], tags: ["nhrc-tenure","3-years","70-years","2019-amendment"] },
  { id: "q-nhrc18", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "An NHRC member can be removed by:", options: ["The Prime Minister at any time", "The President, on grounds of proved misbehaviour or incapacity, after an inquiry by the Supreme Court", "A resolution of both Houses of Parliament", "The NHRC Chairperson"], correctOptionIds: [1], explanation: "Removal is by the President on grounds of proved misbehaviour or incapacity, after an inquiry by the Supreme Court — a genuine security-of-tenure safeguard that mirrors the protection given to the CVC and CIC.", optionExplanations: {"0":"Not the PM.","1":"Correct.","2":"No parliamentary resolution is required.","3":"Not internal removal."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [4], tags: ["nhrc-removal","president","sc-inquiry"] },
  { id: "q-nhrc19", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Which of these changes was made by the 2019 amendment to the Protection of Human Rights Act?", options: ["The NHRC was made a constitutional body", "Tenure was reduced from 5 to 3 years, retired SC judges were made eligible as Chairperson, and the Secretary-General was given administrative and financial powers", "The NHRC was given the power to punish offenders directly", "The armed forces were brought fully within the NHRC's investigative jurisdiction"], correctOptionIds: [1], explanation: "The 2019 amendment reduced the tenure from 5 years to 3 (with reappointment now permitted), widened Chairperson eligibility to include retired Supreme Court judges (previously only a retired CJI), allowed a retired HC judge to chair an SHRC, gave the Secretary-General/Secretary administrative and financial powers, and expanded the NHRC's role in Union Territories.", optionExplanations: {"0":"It remains statutory.","1":"Correct.","2":"Its recommendations remain advisory.","3":"The Section 19 carve-out remains."}, difficulty: "medium", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [3,4,11], tags: ["2019-amendment","tenure","secretary-general","uts"] },

  // ─── NHRC: working & powers ───────────────────────────────────────
  { id: "q-nhrc20", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Complaints to the NHRC must generally relate to violations occurring within:", options: ["Six months of filing", "One year of occurrence", "Three years of occurrence", "There is no limitation period"], correctOptionIds: [1], explanation: "Complaints must generally pertain to violations within one year of occurrence, and are screened by the Law Division before admission. The inability to entertain older complaints is a recognised jurisdictional limitation.", optionExplanations: {"0":"Not six months.","1":"Correct. One year.","2":"Not three years.","3":"There is a one-year limitation."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [4,7], tags: ["one-year-limitation","complaints","law-division"] },
  { id: "q-nhrc21", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The NHRC's Investigation Division is headed by an officer of the rank of:", options: ["Superintendent of Police", "Director General of Police", "District Magistrate", "Secretary to the Government of India"], correctOptionIds: [1], explanation: "On admitting a complaint the NHRC may conduct its own investigation through its Investigation Division, headed by an officer of Director General of Police rank — or alternatively seek a report from the concerned government authority or police.", optionExplanations: {"0":"Too junior.","1":"Correct. DGP rank.","2":"Not a DM.","3":"The Secretary-General handles administration, not investigation."}, difficulty: "hard", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [4], tags: ["investigation-division","dgp-rank"] },
  { id: "q-nhrc22", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "While conducting an inquiry, the NHRC has:", options: ["The powers of a criminal court, including sentencing", "The powers of a civil court — summoning witnesses, requisitioning documents, recording evidence on oath", "Only the power to write to the government", "The power to issue binding writs"], correctOptionIds: [1], explanation: "During inquiries the NHRC exercises the powers of a civil court under the Code of Civil Procedure — summoning and examining witnesses, requisitioning public records, and receiving evidence on affidavit. It cannot sentence or issue writs itself; it may APPROACH the SC or a High Court for writs.", optionExplanations: {"0":"It cannot punish or sentence.","1":"Correct.","2":"It has substantive inquiry powers.","3":"Only courts issue writs; the NHRC can only move them."}, difficulty: "medium", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [4], tags: ["civil-court-powers","inquiry","cpc"] },
  { id: "q-nhrc23", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Under Section 18, after completing an inquiry the NHRC may do all of the following EXCEPT:", options: ["Recommend payment of compensation to the victim", "Recommend prosecution or disciplinary action against the responsible public servant", "Itself award compensation and punish the guilty official", "Approach the Supreme Court or the concerned High Court for writs and directions"], correctOptionIds: [2], explanation: "Section 18 gives the NHRC power to RECOMMEND compensation, prosecution or disciplinary action and other corrective measures, and to approach the SC or a High Court. It cannot itself award compensation or impose punishment — the core reason its recommendations are called 'advisory yet influential'.", optionExplanations: {"0":"It can recommend this.","1":"It can recommend this.","2":"Correct answer — it cannot itself award or punish.","3":"It can do this."}, difficulty: "medium", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [4], tags: ["section-18","recommendatory","no-enforcement"] },
  { id: "q-nhrc24", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Under Section 19 of the Protection of Human Rights Act, in matters involving the armed forces the NHRC:", options: ["Can conduct a full independent investigation", "Can only seek a report from the Central Government, and thereafter close the case or make recommendations", "Has no role whatsoever", "Must refer the matter to a court martial"], correctOptionIds: [1], explanation: "Section 19 prescribes a distinct process: the NHRC (on its own motion or on a complaint) may only seek a REPORT FROM THE CENTRAL GOVERNMENT regarding alleged violations by armed forces personnel. After examining it, the Commission may close the case or make recommendations — and the Centre must inform the NHRC of action taken within three months.", optionExplanations: {"0":"It has no direct investigative authority here.","1":"Correct.","2":"It does retain an oversight and dialogue role.","3":"No such referral mechanism."}, difficulty: "medium", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [4,5], tags: ["section-19","armed-forces","central-government"] },
  { id: "q-nhrc25", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "In armed forces cases, within what period must the Central Government inform the NHRC of the action taken on its recommendations?", options: ["One month", "Three months", "Six months", "One year"], correctOptionIds: [1], explanation: "Three months, or such extended time as the Commission may allow. Note the contrast: for ordinary recommendations, the concerned ministry or state must submit an Action Taken Report within ONE MONTH.", optionExplanations: {"0":"One month is the ATR deadline for ordinary recommendations.","1":"Correct. Three months for armed forces cases.","2":"Not six months.","3":"Not one year."}, difficulty: "hard", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [5], tags: ["three-months","armed-forces","section-19"] },
  { id: "q-nhrc26", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The Action Taken Report on NHRC recommendations must be submitted by the concerned ministry or state government within:", options: ["One month", "Three months", "Six months", "No fixed period"], correctOptionIds: [0], explanation: "The concerned ministry or state government must submit an Action Taken Report within one month. The NHRC reviews compliance and may publish non-compliance in its annual report, which is tabled before Parliament — ensuring public accountability even without binding force.", optionExplanations: {"0":"Correct. One month.","1":"Three months applies to armed forces cases.","2":"Not six months.","3":"There is a fixed period."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [5], tags: ["action-taken-report","one-month","annual-report"] },
  { id: "q-nhrc27", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The NHRC can intervene in ongoing court proceedings involving human rights allegations:", options: ["As a matter of right, without any permission", "With the approval of the court concerned", "Only in the Supreme Court", "It cannot intervene in judicial proceedings at all"], correctOptionIds: [1], explanation: "Under its Section 12 functions, the NHRC may intervene in any proceeding involving allegations of human rights violation pending before a court — but only WITH THE APPROVAL OF THAT COURT, ensuring judicial redress incorporates a rights-based perspective.", optionExplanations: {"0":"Court approval is required.","1":"Correct.","2":"Not confined to the SC.","3":"It can intervene, with approval."}, difficulty: "medium", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [5], tags: ["judicial-intervention","section-12","court-approval"] },
  { id: "q-nhrc28", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The functions of the NHRC are principally enumerated in:", options: ["Section 12 of the Protection of Human Rights Act, 1993", "Section 30 of the Act", "Article 338 of the Constitution", "The NHRC (Procedure) Regulations, 1994 alone"], correctOptionIds: [0], explanation: "Section 12 entrusts the NHRC with its broad quasi-judicial, advisory and educational functions. Sections 17-18 cover inquiry and post-inquiry steps, Section 19 the armed forces procedure, Section 29 the SHRC's powers, and Section 30 Human Rights Courts.", optionExplanations: {"0":"Correct. Section 12.","1":"Section 30 = Human Rights Courts.","2":"Art 338 = National Commission for Scheduled Castes.","3":"The Regulations govern procedure, not the mandate."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [5], tags: ["section-12","functions","statute-map"] },
  { id: "q-nhrc29", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The NHRC's inspection of jails and custodial institutions is aligned with which international standard?", options: ["UN Mandela Rules (2015)", "Paris Agreement (2015)", "Geneva Conventions (1949)", "Rome Statute (1998)"], correctOptionIds: [0], explanation: "The Commission visits jails, detention centres, juvenile homes and psychiatric facilities to study conditions of inmates and recommend reforms, aligning with the UN Mandela Rules (2015) — the Standard Minimum Rules for the Treatment of Prisoners.", optionExplanations: {"0":"Correct. UN Mandela Rules, 2015.","1":"That is a climate agreement.","2":"Those govern armed conflict.","3":"That established the International Criminal Court."}, difficulty: "hard", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [5], tags: ["mandela-rules","prison-inspection","2015"] },

  // ─── NHRC: role & limitations ─────────────────────────────────────
  { id: "q-nhrc30", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "In NHRC v. State of Arunachal Pradesh (1996), the Supreme Court:", options: ["Held that the NHRC's recommendations are binding", "Upheld the NHRC's locus standi to move the court for refugee protection — the Chakma community case", "Struck down Section 19 of the Protection of Human Rights Act", "Made the NHRC a constitutional body"], correctOptionIds: [1], explanation: "The SC upheld the NHRC's locus standi to approach the court on behalf of the Chakma refugee community in Arunachal Pradesh — judicial recognition of the Commission's role as a complementary oversight institution.", optionExplanations: {"0":"Recommendations remain advisory.","1":"Correct.","2":"Section 19 stands.","3":"It remains statutory."}, difficulty: "hard", skill: "judgment-analysis", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [6], tags: ["nhrc-v-arunachal-pradesh","1996","chakma","locus-standi"] },
  { id: "q-nhrc31", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "NHRC guidelines on custodial deaths were significantly shaped by, and in turn fed into, which landmark case?", options: ["Maneka Gandhi v. Union of India (1978)", "D.K. Basu v. State of West Bengal (1997)", "Vishakha v. State of Rajasthan (1997)", "S.R. Bommai v. Union of India (1994)"], correctOptionIds: [1], explanation: "The NHRC issued detailed guidelines on custodial deaths, connected with D.K. Basu v. State of West Bengal (1997), which later shaped Supreme Court jurisprudence on arrest and detention safeguards. The NHRC also critiqued misuse of POTA and TADA.", optionExplanations: {"0":"Maneka Gandhi concerned procedure established by law and Art 21.","1":"Correct. D.K. Basu (1997).","2":"Vishakha concerned workplace sexual harassment.","3":"Bommai concerned President's Rule."}, difficulty: "medium", skill: "judgment-analysis", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [6], tags: ["dk-basu","1997","custodial-deaths","guidelines"] },
  { id: "q-nhrc32", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "In the Punjab mass cremations case (1995-2012), the NHRC directed:", options: ["Prosecution of all police officers involved", "₹1.75 lakh compensation each to 1,051 families whose kin were unlawfully cremated", "A CBI investigation into every case", "Closure of the case for want of evidence"], correctOptionIds: [1], explanation: "The NHRC directed ₹1.75 lakh compensation each to 1,051 families whose kin had been unlawfully cremated — a landmark for dignity rights and one of the Commission's most cited achievements.", optionExplanations: {"0":"It recommended compensation, not blanket prosecution.","1":"Correct.","2":"Not the direction given.","3":"The case produced substantial relief."}, difficulty: "hard", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [6], tags: ["punjab-mass-cremations","compensation","1051-families"] },
  { id: "q-nhrc33", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Which NHRC Chairperson described the Commission as a 'toothless tiger' in 2016?", options: ["Justice P.C. Ghosh", "Justice H.L. Dattu", "Justice Amitava Roy", "Justice D.K. Basu"], correctOptionIds: [1], explanation: "Justice H.L. Dattu, then Chairperson of the NHRC, called the Commission a 'toothless tiger' in a 2016 interview, citing its lack of power to enforce recommendations. The Supreme Court used the same phrase in the Manipur extra-judicial killings case.", optionExplanations: {"0":"Justice P.C. Ghosh was the first Lokpal chairperson.","1":"Correct. Justice H.L. Dattu.","2":"Justice Amitava Roy headed the prison decongestion committee.","3":"D.K. Basu is a case name, not a chairperson."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [7], tags: ["toothless-tiger","hl-dattu","2016"] },
  { id: "q-nhrc34", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "GANHRI, which downgraded India's NHRC accreditation in 2017, is:", options: ["A UN treaty body that adjudicates human rights complaints", "The Global Alliance of National Human Rights Institutions, which accredits national human rights bodies", "An Indian civil society coalition", "A committee of the Ministry of Home Affairs"], correctOptionIds: [1], explanation: "GANHRI — the Global Alliance of National Human Rights Institutions — accredits NHRIs worldwide against the Paris Principles. It downgraded India's NHRC from 'A' grade in 2017 citing political interference and lack of pluralism, and its 2024-25 reports again flagged an opaque selection process, unadvertised vacancies, weak follow-up and inadequate civil society participation.", optionExplanations: {"0":"It accredits; it does not adjudicate complaints.","1":"Correct.","2":"It is a global body.","3":"Not a government committee."}, difficulty: "medium", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [6,7], tags: ["ganhri","accreditation","downgrade-2017"] },
  { id: "q-nhrc35", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Which of the following is NOT a limitation of the NHRC?", options: ["Its recommendations are advisory and not binding", "It cannot entertain complaints older than one year", "It cannot visit jails or detention centres", "It cannot directly investigate violations by the armed forces"], correctOptionIds: [2], explanation: "Visiting jails, detention centres, juvenile homes and psychiatric facilities is one of the NHRC's express FUNCTIONS, not a limitation. The genuine limitations are the advisory nature of recommendations, the one-year limitation, the private-actor exclusion, and the armed forces carve-out.", optionExplanations: {"0":"A real limitation.","1":"A real limitation.","2":"Correct answer — inspection of custodial institutions is a power, not a bar.","3":"A real limitation under Section 19."}, difficulty: "medium", skill: "elimination", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [5,7], tags: ["limitations","elimination","prison-visits"] },
  { id: "q-nhrc36", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The NHRC cannot entertain complaints of human rights violations by private individuals unless:", options: ["The violation involves more than one victim", "State complicity is proved", "A court refers the matter", "The complaint is filed by an NGO"], correctOptionIds: [1], explanation: "The NHRC cannot entertain cases of violations by private individuals unless state complicity is established — a jurisdictional gap that the reform agenda seeks to close by extending its jurisdiction to private actors, especially relevant in the business and human rights context.", optionExplanations: {"0":"Victim count is irrelevant.","1":"Correct.","2":"Court reference is a separate route for state violations.","3":"NGOs may file, but that does not cure the private-actor bar."}, difficulty: "hard", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [7], tags: ["private-actors","state-complicity","jurisdiction"] },

  // ─── SHRC & Human Rights Courts ───────────────────────────────────
  { id: "q-nhrc37", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "A State Human Rights Commission consists of:", options: ["A Chairperson and 2 members", "A Chairperson, 5 members and 7 ex-officio members", "A Chairperson and 4 members", "A single Commissioner"], correctOptionIds: [0], explanation: "An SHRC has a Chairperson and 2 members: one who is a serving or retired High Court judge or a District Judge with at least seven years' experience, and one with expertise in human rights. Unlike the NHRC, it has no ex-officio members.", optionExplanations: {"0":"Correct.","1":"That is the NHRC's composition.","2":"Not 5 in total.","3":"It is a collegial body."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [11], tags: ["shrc","composition","chairperson-plus-two"] },
  { id: "q-nhrc38", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The Chairperson and members of a State Human Rights Commission are appointed by:", options: ["The President, on the PM's recommendation", "The Governor, on the recommendation of a committee headed by the Chief Minister", "The Chief Minister directly", "The Chief Justice of the High Court"], correctOptionIds: [1], explanation: "The Governor appoints on the recommendation of a committee headed by the Chief Minister, including the Speaker of the Assembly, the State Home Minister and the Leader of Opposition in the Assembly — plus the Chairman and LoP of the Legislative Council in bicameral states.", optionExplanations: {"0":"The President appoints the NHRC, not the SHRC.","1":"Correct.","2":"The CM heads the recommending committee; the Governor appoints.","3":"The HC Chief Justice is consulted only where a sitting judge is appointed."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [11], tags: ["shrc","governor","chief-minister-committee"] },
  { id: "q-nhrc39", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Who can remove the Chairperson of a State Human Rights Commission?", options: ["The Governor", "Only the President", "The Chief Minister", "The State Legislature"], correctOptionIds: [1], explanation: "Although the GOVERNOR appoints, only the PRESIDENT can remove an SHRC Chairperson or member — on grounds such as insolvency, infirmity, conviction or misbehaviour, proved by a Supreme Court inquiry. This asymmetry is a favourite prelims trap.", optionExplanations: {"0":"The Governor appoints but cannot remove.","1":"Correct. Only the President.","2":"Not the CM.","3":"Not the legislature."}, difficulty: "hard", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [12], tags: ["shrc-removal","president-not-governor","trap"] },
  { id: "q-nhrc40", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The annual report of a State Human Rights Commission is laid before:", options: ["Parliament", "The State Legislature", "The NHRC", "The Governor only"], correctOptionIds: [1], explanation: "The SHRC's annual report is laid before the State Legislature; the NHRC's annual report is tabled before Parliament. Persistent non-compliance is highlighted publicly in these reports, exerting moral and political pressure.", optionExplanations: {"0":"Parliament receives the NHRC's report.","1":"Correct.","2":"The SHRC liaises with the NHRC but reports to the legislature.","3":"The Governor receives it, but it is laid before the legislature."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [13], tags: ["shrc-annual-report","state-legislature"] },
  { id: "q-nhrc41", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Human Rights Courts are provided for under which section, and what is required for their establishment?", options: ["Section 12 — a Presidential notification", "Section 30 — the State Government notifies a court for each district with the CONCURRENCE of the Chief Justice of the High Court", "Section 19 — a Central Government order", "Section 31 — a resolution of the State Legislature"], correctOptionIds: [1], explanation: "Under Section 30 the State Government, with the CONCURRENCE of the Chief Justice of the High Court, may notify a Human Rights Court for each district. In most states the Sessions Court is simply designated for the purpose.", optionExplanations: {"0":"Section 12 = NHRC functions.","1":"Correct. Section 30, with HC Chief Justice's concurrence.","2":"Section 19 = armed forces procedure.","3":"Section 31 = Special Public Prosecutor."}, difficulty: "medium", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [13], tags: ["section-30","human-rights-courts","concurrence"] },
  { id: "q-nhrc42", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "Under Section 31, the Special Public Prosecutor for a Human Rights Court must be:", options: ["A retired judge of the High Court", "A practising advocate with at least seven years' experience", "A serving District Judge", "An officer of the State Law Department"], correctOptionIds: [1], explanation: "Section 31 requires the State Government to appoint a Special Public Prosecutor for every Human Rights Court, who must be a practising advocate with at least seven years' experience — ensuring specialised handling of human rights litigation.", optionExplanations: {"0":"Not a retired HC judge.","1":"Correct. 7 years at the bar.","2":"The judge presides; the SPP prosecutes.","3":"Must be a practising advocate."}, difficulty: "hard", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [13], tags: ["section-31","special-public-prosecutor","seven-years"] },
  { id: "q-nhrc43", subject: "polity", lessonIds: ["nhrc-01"], type: "single-correct", prompt: "The functional significance of Human Rights Courts, compared with the NHRC and SHRCs, is that they:", options: ["Have the same recommendatory powers", "Provide JUDICIAL ENFORCEMENT — trying offences and awarding punishments — bridging the gap left by recommendation-only bodies", "Only conduct awareness programmes", "Supervise the SHRCs"], correctOptionIds: [1], explanation: "While the NHRC and SHRCs perform investigative and recommendatory roles, Human Rights Courts provide judicial enforcement by trying offences and awarding punishments — bridging recommendation and enforcement. In practice, though, they remain sporadic and underutilised.", optionExplanations: {"0":"They are courts, not recommending bodies.","1":"Correct.","2":"Awareness is the commissions' function.","3":"They do not supervise SHRCs."}, difficulty: "medium", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [13], tags: ["human-rights-courts","enforcement","underutilised"] },

  // ─── Multiple statements / AR / match ─────────────────────────────
  { id: "q-nhrc44", subject: "polity", lessonIds: ["nhrc-01"], type: "multiple-statements", prompt: "Consider the following statements regarding the National Human Rights Commission of India: (adapted from UPSC 1999)\n1. Its Chairperson must be a retired Chief Justice of India.\n2. It has formations in each state as the State Human Rights Commission.\n3. Its powers are only recommendatory in nature.\n4. It is mandatory to appoint a woman as a member of the Commission.\n\nWhich of the above are correct TODAY?", statements: ["Chairperson must be retired CJI", "SHRCs in states", "Powers recommendatory", "Woman member mandatory"], options: ["1, 2, 3 and 4", "2, 3 and 4 only", "1 and 3 only", "2 and 3 only"], correctOptionIds: [1], explanation: "Statements 2, 3 and 4 are correct. Statement 1 is now WRONG: since the 2019 amendment the Chairperson may be a retired CJI OR a retired Judge of the Supreme Court. (In the original 1999 question the answer was '1 and 3' — a good illustration of why amendment-tracking matters.)", optionExplanations: {"0":"Statement 1 no longer holds after 2019.","1":"Correct.","2":"Statement 1 is outdated, and 2 and 4 are also correct.","3":"Statement 4 is correct too — a woman member is mandatory."}, difficulty: "hard", skill: "elimination", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [3,14], tags: ["pyq-1999","nhrc","statements","2019-amendment"] },
  { id: "q-nhrc45", subject: "polity", lessonIds: ["nhrc-01"], type: "multiple-statements", prompt: "Consider the following about the NHRC:\n1. It is a constitutional body.\n2. Its Chairperson and members hold office for 3 years or until age 70.\n3. Its members can be removed by the President after a Supreme Court inquiry.\n4. It has the powers of a civil court while conducting inquiries.\n\nWhich are correct?", statements: ["Constitutional body", "3 years or 70", "Removal by President after SC inquiry", "Civil court powers"], options: ["2, 3 and 4 only", "1, 2 and 3 only", "1 and 4 only", "All of the above"], correctOptionIds: [0], explanation: "Statements 2, 3, 4 are correct. Statement 1 is WRONG — the NHRC is a STATUTORY body under the Protection of Human Rights Act, 1993. Contrast the NCSC (Art 338) and NCST (Art 338A), which ARE constitutional.", optionExplanations: {"0":"Correct. Statement 1 is wrong.","1":"Statement 1 is wrong.","2":"Statement 1 is wrong; 2 and 3 are correct.","3":"Statement 1 is wrong."}, difficulty: "medium", skill: "elimination", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [3,4], tags: ["nhrc","statements","statutory-not-constitutional"] },
  { id: "q-nhrc46", subject: "polity", lessonIds: ["nhrc-01"], type: "assertion-reason", prompt: "Assertion (A): The NHRC has been described as a 'toothless tiger'.\nReason (R): The NHRC's recommendations are advisory in nature and it cannot itself impose penalties or award compensation.", options: ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], correctOptionIds: [0], explanation: "Both are true and R explains A. Precisely because the NHRC's findings are recommendations — it can recommend compensation, prosecution or disciplinary action but cannot award or impose either — its own Chairperson Justice H.L. Dattu and the Supreme Court have called it a 'toothless tiger'.", optionExplanations: {"0":"Correct.","1":"R is exactly the reason for the description.","2":"R is true.","3":"A is true."}, difficulty: "medium", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [7], tags: ["assertion-reason","toothless-tiger","recommendatory"] },
  { id: "q-nhrc47", subject: "polity", lessonIds: ["nhrc-01"], type: "assertion-reason", prompt: "Assertion (A): The Governor appoints the Chairperson of a State Human Rights Commission but cannot remove them.\nReason (R): Only the President can remove an SHRC Chairperson, on proved grounds after a Supreme Court inquiry.", options: ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], correctOptionIds: [0], explanation: "Both are true and R explains A. The Protection of Human Rights Act deliberately vests removal in the President alone, insulating SHRC members from the state executive that appointed them — a safeguard for independence.", optionExplanations: {"0":"Correct.","1":"R is the direct reason A holds.","2":"R is true.","3":"A is true."}, difficulty: "hard", skill: "understanding", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [11,12], tags: ["assertion-reason","shrc","governor","president"] },
  { id: "q-nhrc48", subject: "polity", lessonIds: ["nhrc-01"], type: "match-following", prompt: "Match the section of the Protection of Human Rights Act, 1993 with its subject:\nA. Section 12 → 1. Special Public Prosecutor\nB. Section 19 → 2. Functions of the NHRC\nC. Section 30 → 3. Procedure regarding armed forces\nD. Section 31 → 4. Human Rights Courts", statements: ["A-Section 12","B-Section 19","C-Section 30","D-Section 31"], options: ["A-2, B-3, C-4, D-1", "A-1, B-2, C-3, D-4", "A-2, B-4, C-3, D-1", "A-3, B-2, C-1, D-4"], correctOptionIds: [0], explanation: "Section 12 = functions of the NHRC (A-2). Section 19 = procedure regarding armed forces (B-3). Section 30 = Human Rights Courts (C-4). Section 31 = Special Public Prosecutor (D-1). Also worth remembering: Sections 17-18 = inquiry and post-inquiry steps; Section 29 = SHRC powers.", optionExplanations: {"0":"Correct.","1":"Incorrect.","2":"Incorrect.","3":"Incorrect."}, difficulty: "hard", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [5,13], tags: ["match","sections","statute-map"] },
  { id: "q-nhrc49", subject: "polity", lessonIds: ["nhrc-01"], type: "match-following", prompt: "Match the NHRC intervention with the case:\nA. Suo motu cognisance of mass graves → 1. Manipur extra-judicial killings (2013-16)\nB. ₹1.75 lakh compensation to 1,051 families → 2. Gujarat riots (2002)\nC. SC-monitored SIT on 1,528 alleged fake encounters → 3. Punjab mass cremations (1995-2012)", statements: ["A-mass graves","B-compensation to 1,051 families","C-1,528 fake encounters"], options: ["A-2, B-3, C-1", "A-1, B-2, C-3", "A-3, B-1, C-2", "A-2, B-1, C-3"], correctOptionIds: [0], explanation: "Mass graves = Gujarat riots, 2002 (A-2). ₹1.75 lakh to 1,051 families = Punjab mass cremations (B-3). SIT on 1,528 alleged fake encounters = Manipur, where the SC called the NHRC a 'toothless tiger' (C-1).", optionExplanations: {"0":"Correct.","1":"Incorrect.","2":"Incorrect.","3":"Incorrect."}, difficulty: "hard", skill: "recall", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [6], tags: ["match","interventions","gujarat","punjab","manipur"] },
  { id: "q-nhrc50", subject: "polity", lessonIds: ["nhrc-01"], type: "multiple-statements", prompt: "Consider the following about State Human Rights Commissions:\n1. The Chairperson may be a retired Chief Justice or Judge of a High Court.\n2. Tenure is 3 years or age 70.\n3. In armed forces matters the SHRC seeks a report from the State Government.\n4. After demitting office, the Chairperson and members cannot hold employment under the State or Central Government.\n\nWhich are correct?", statements: ["Retired HC CJ or judge", "3 years or 70", "Report from State Government in armed forces matters", "Post-tenure employment bar"], options: ["1, 2 and 4 only", "1, 2 and 3 only", "2, 3 and 4 only", "All of the above"], correctOptionIds: [0], explanation: "Statements 1, 2, 4 are correct. Statement 3 is WRONG — even for the SHRC, the Section 19 route requires a report from the CENTRAL Government in armed or paramilitary force cases, and the Centre must report back within three months.", optionExplanations: {"0":"Correct. Statement 3 is wrong.","1":"Statement 3 is wrong.","2":"Statement 3 is wrong; 1 is correct.","3":"Statement 3 is wrong."}, difficulty: "hard", skill: "elimination", upscTrack: "prelims", sourceFiles: ["80774431_NHRC.pdf"], sourcePages: [11,12,13], tags: ["shrc","statements","section-19","post-tenure-bar"] },
];
